-- ZOKY Admin: choose where ZOKY serves (Founder 2026-11-02: "ให้ Admin เลือกได้ว่า
-- จะเปิดให้บริการที่ไหนบ้าง"; choices: whole country + each of the 77 provinces,
-- in ZOKY Admin, super admin only).
--
-- Additive. internal.food_in_service_area (WYN-211) already accepts a point
-- inside ANY active row of public.food_service_areas and is not changed, so
-- every quote, order, store readiness check and area-check RPC follows what
-- the super admin turns on. This migration:
-- * adds group_code / kind / name_en / sort_order to food_service_areas;
--   "TH" (the existing Thailand row) is the whole country, "TH-xx" a province;
-- * adds 76 province rows, all OFF (Maha Sarakham is the existing
--   maha_sarakham row, grouped as TH-44 and left as it is). Live behaviour does
--   not change: Thailand and Maha Sarakham stay on;
-- * admin_zoky_service_areas() (food view or super admin) and
--   admin_zoky_set_service_area() (super admin only, audited, refuses to turn
--   off the last open area);
-- * food_service_area_overview() and food_service_area_boundaries() for the
--   customer/merchant map and wording (public geography only).
--
-- Province boundaries: OpenStreetMap admin_level 4 relations (ids from Wikidata
-- P402), (c) OpenStreetMap contributors, ODbL. Kanchanaburi (TH-71), whose OSM
-- polygon could not be generated, is Thailand minus the other 76 provinces.
-- Douglas-Peucker 0.003 degrees (about 330 m). Re-running keeps each area's
-- on/off state.
-- Rollback: supabase/rollbacks/20261103100000_zoky_service_area_admin_rollback.sql

alter table public.food_service_areas
  add column if not exists group_code text,
  add column if not exists kind text,
  add column if not exists name_en text,
  add column if not exists sort_order integer;

update public.food_service_areas
   set group_code = 'TH', kind = 'country', name = 'ประเทศไทย', name_en = 'Thailand', sort_order = 0
 where code = 'thailand';
update public.food_service_areas
   set group_code = 'TH-44', kind = 'province', name = 'มหาสารคาม', name_en = 'Maha Sarakham', sort_order = 44
 where code = 'maha_sarakham';
-- Any other hand-made area keeps working as its own group.
update public.food_service_areas
   set group_code = code, kind = 'custom', sort_order = coalesce(sort_order, 1000)
 where group_code is null;

insert into public.food_service_areas
  (code, group_code, kind, name, name_en, sort_order, active, min_lat, max_lat, min_lng, max_lng, lats, lngs)
