alter table public.food_service_areas alter column group_code set not null;
alter table public.food_service_areas alter column kind set not null;
alter table public.food_service_areas alter column sort_order set default 1000;
do $$ begin
  alter table public.food_service_areas add constraint food_service_areas_kind check (kind in ('country', 'province', 'custom'));
exception when duplicate_object then null; end $$;
create index if not exists food_service_areas_group_idx on public.food_service_areas (group_code);

-- Audit event type (same pattern as 20261025100000_zoky_admin_team_v1.sql).
do $$
declare
  v_name text;
  v_def text;
  v_values text[];
  v_new text[] := array['zoky_service_area_changed'];
begin
  if to_regclass('public.audit_log') is null then return; end if;
  select c.conname, pg_get_constraintdef(c.oid) into v_name, v_def
  from pg_constraint c
  where c.conrelid = 'public.audit_log'::regclass and c.contype = 'c'
    and pg_get_constraintdef(c.oid) like '%event_type%'
  limit 1;
  if v_def is null then return; end if;  -- no event-type constraint to extend
  select array_agg(distinct x.m[1] order by x.m[1]) into v_values
  from regexp_matches(v_def, '''([a-z0-9_]+)''', 'g') as x(m);
  if v_values is null then
    select array_agg(distinct btrim(v) order by btrim(v)) into v_values
    from regexp_matches(v_def, '''\{([^}]*)\}''') as x(m), unnest(string_to_array(x.m[1], ',')) as v;
  end if;
  if v_values is null or cardinality(v_values) < 2
     or exists (select 1 from unnest(v_values) as v where v !~ '^[a-z0-9_]+$') then
    raise exception 'Could not read the audit_log event types from: %', v_def;
  end if;
  if v_new <@ v_values then return; end if;
  select array_agg(distinct v order by v) into v_values from unnest(v_values || v_new) as v;
  execute format('alter table public.audit_log drop constraint %I', v_name);
  execute format('alter table public.audit_log add constraint audit_log_event_type_check check (event_type in (%s))',
    (select string_agg(quote_literal(v), ', ') from unnest(v_values) as v));
end
$$;

-- Admin list: one entry per area (country first, then provinces in ISO order).
create or replace function public.admin_zoky_service_areas()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_result jsonb;
begin
  if (select auth.uid()) is null or not (internal.is_super_admin() or internal.has_admin_permission('food', 'view')) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'can_edit', internal.is_super_admin(),
    'areas', coalesce(jsonb_agg(jsonb_build_object(
        'group_code', g.group_code, 'kind', g.kind, 'name', g.name, 'name_en', g.name_en,
        'active', g.active, 'updated_at', g.updated_at
      ) order by case g.kind when 'country' then 0 when 'province' then 1 else 2 end, g.sort_order, g.group_code), '[]'::jsonb))
  into v_result
  from (
    select a.group_code, min(a.kind) as kind, min(a.name) as name, min(a.name_en) as name_en,
           min(a.sort_order) as sort_order, bool_or(a.active) as active, max(a.updated_at) as updated_at
    from public.food_service_areas a
    group by a.group_code
  ) g;
  return v_result;
end;
$$;
revoke all on function public.admin_zoky_service_areas() from public, anon;
grant execute on function public.admin_zoky_service_areas() to authenticated;

-- Super admin only. Turning an area off never leaves ZOKY with no open area.
create or replace function public.admin_zoky_set_service_area(p_group_code text, p_active boolean)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_name text;
  v_changed integer;
begin
  if v_actor is null or not internal.is_super_admin() then
    raise exception 'Only the super admin can change ZOKY service areas' using errcode = '42501';
  end if;
  if p_group_code is null or p_active is null then
    raise exception 'Area and state are required' using errcode = '22023';
  end if;
  -- One change at a time, so two admins cannot both turn off the last areas.
  perform pg_advisory_xact_lock(hashtext('zoky_service_area'));
  select min(name) into v_name from public.food_service_areas where group_code = p_group_code;
  if v_name is null then
    raise exception 'Service area not found' using errcode = 'P0002';
  end if;
  if not p_active and not exists (
    select 1 from public.food_service_areas where active and group_code <> p_group_code
  ) then
    raise exception 'At least one service area must stay open' using errcode = '22023';
  end if;
  update public.food_service_areas
     set active = p_active, updated_at = now()
   where group_code = p_group_code and active is distinct from p_active;
  get diagnostics v_changed = row_count;
  if v_changed > 0 then
    perform internal.log_audit_event(v_actor, 'zoky_service_area_changed', null,
      jsonb_build_object('group_code', p_group_code, 'name', v_name, 'active', p_active));
  end if;
  return jsonb_build_object('group_code', p_group_code, 'active', p_active, 'changed', v_changed > 0);
end;
$$;
revoke all on function public.admin_zoky_set_service_area(text, boolean) from public, anon;
grant execute on function public.admin_zoky_set_service_area(text, boolean) to authenticated;

-- Customer/merchant wording: whole country, or the open provinces by name.
create or replace function public.food_service_area_overview()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'nationwide', exists (select 1 from public.food_service_areas where active and kind = 'country'),
    'areas', coalesce((
      select jsonb_agg(jsonb_build_object('code', g.group_code, 'name', g.name, 'name_en', g.name_en) order by g.sort_order, g.group_code)
      from (
        select a.group_code, min(a.name) as name, min(a.name_en) as name_en, min(a.sort_order) as sort_order
        from public.food_service_areas a
        where a.active and a.kind <> 'country'
        group by a.group_code
      ) g
    ), '[]'::jsonb)
  );
$$;
revoke all on function public.food_service_area_overview() from public;
grant execute on function public.food_service_area_overview() to anon, authenticated;

-- Open areas as GeoJSON for the map. With the whole country open, only the
-- country outline is returned. Public administrative geography only.
create or replace function public.food_service_area_boundaries()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with nationwide as (
    select exists (select 1 from public.food_service_areas where active and kind = 'country') as yes
  )
  select jsonb_build_object('type', 'FeatureCollection', 'features', coalesce(jsonb_agg(jsonb_build_object(
      'type', 'Feature',
      'properties', jsonb_build_object('code', a.group_code, 'name', a.name),
      'geometry', jsonb_build_object('type', 'Polygon', 'coordinates', jsonb_build_array(
        (select jsonb_agg(jsonb_build_array(a.lngs[x.i], a.lats[x.i]) order by s.n)
           from generate_series(1, cardinality(a.lats) + 1) as s(n),
                lateral (select case when s.n > cardinality(a.lats) then 1 else s.n end as i) x)
      ))
    ) order by a.sort_order, a.code), '[]'::jsonb))
  from public.food_service_areas a, nationwide
  where a.active and (a.kind = 'country' or not nationwide.yes);
$$;
revoke all on function public.food_service_area_boundaries() from public;
grant execute on function public.food_service_area_boundaries() to anon, authenticated;
